var username = env.get('ZAPTEC_USERNAME') || '';
var password = env.get('ZAPTEC_PASSWORD') || '';

if (!username || !password) {
    node.error('Zaptec inloggegevens niet geconfigureerd! Stel omgevingsvariabelen ZAPTEC_USERNAME en ZAPTEC_PASSWORD in.');
    return null;
}

msg.url = 'https://api.zaptec.com/oauth/token';
msg.method = 'POST';
msg.headers = {
    'Content-Type': 'application/x-www-form-urlencoded',
    'Accept': 'application/json'
};
msg.payload = 'grant_type=password&username=' + encodeURIComponent(username) + '&password=' + encodeURIComponent(password);

return msg;

if (msg.statusCode !== 200) {
    node.error('Zaptec authenticatie mislukt (HTTP ' + msg.statusCode + '): ' + JSON.stringify(msg.payload));
    return null;
}

if (!msg.payload || !msg.payload.access_token) {
    node.error('Geen access_token ontvangen van Zaptec: ' + JSON.stringify(msg.payload));
    return null;
}

var expiresIn = msg.payload.expires_in || 3600;
var expiryTime = Date.now() + (expiresIn - 120) * 1000;

flow.set('zaptec_token', msg.payload.access_token);
flow.set('zaptec_token_expiry', expiryTime);
flow.set('zaptec_token_type', msg.payload.token_type || 'Bearer');

var expiryDate = new Date(expiryTime);
node.log('Zaptec token opgeslagen, geldig tot: ' + expiryDate.toLocaleTimeString());

msg.payload = {
    status: 'success',
    message: 'Token opgeslagen',
    expires_at: expiryDate.toISOString(),
    token_preview: msg.payload.access_token.substring(0, 20) + '...'
};

return msg;

node.error('Authenticatie fout: ' + msg.error.message);
flow.set('zaptec_token', null);
flow.set('zaptec_token_expiry', null);

msg.payload = {
    status: 'error',
    error: msg.error.message,
    timestamp: new Date().toISOString()
};

return msg;

var token = flow.get('zaptec_token');
var expiry = flow.get('zaptec_token_expiry');

if (!token) {
    node.warn('Geen Zaptec token beschikbaar – wacht op authenticatie');
    return null;
}

if (expiry && Date.now() > expiry) {
    node.warn('Zaptec token verlopen – wacht op vernieuwing');
    return null;
}

msg.url = 'https://api.zaptec.com/api/chargers';
msg.method = 'GET';
msg.headers = {
    'Authorization': 'Bearer ' + token,
    'Accept': 'application/json'
};
msg.payload = {};

return msg;

if (msg.statusCode === 401) {
    node.warn('Zaptec API: Niet geautoriseerd (401) – token vernieuwen');
    flow.set('zaptec_token', null);
    return null;
}

if (msg.statusCode !== 200) {
    node.error('Fout bij ophalen laadpalen (HTTP ' + msg.statusCode + '): ' + JSON.stringify(msg.payload));
    return null;
}

var chargers = (msg.payload && msg.payload.Data) ? msg.payload.Data : [];

if (chargers.length === 0) {
    node.warn('Geen laadpalen gevonden in Zaptec account');
    return null;
}

node.log('Gevonden laadpalen: ' + chargers.length);

var token = flow.get('zaptec_token');
var messages = [];

for (var i = 0; i < chargers.length; i++) {
    var c = chargers[i];
    messages.push({
        payload: {},
        charger_id: c.Id,
        charger_serial: (c.SerialNo || c.Id).replace(/[^a-zA-Z0-9_]/g, '_'),
        charger_name: c.Name || ('Laadpaal ' + (i + 1)),
        charger_mid: c.MID || '',
        url: 'https://api.zaptec.com/api/chargers/' + c.Id + '/state',
        method: 'GET',
        headers: {
            'Authorization': 'Bearer ' + token,
            'Accept': 'application/json'
        }
    });
}

return [messages];

if (msg.statusCode === 401) {
    node.warn('Zaptec API: Niet geautoriseerd (401) voor laadpaal ' + msg.charger_serial);
    flow.set('zaptec_token', null);
    return null;
}

if (msg.statusCode !== 200) {
    node.error('Fout bij ophalen staat van ' + msg.charger_serial + ' (HTTP ' + msg.statusCode + ')');
    return null;
}

var states = Array.isArray(msg.payload) ? msg.payload : [];
var serial = msg.charger_serial;
var name = msg.charger_name;

var stateMap = {};
for (var i = 0; i < states.length; i++) {
    var val = parseFloat(states[i].ValueAsString);
    stateMap[states[i].StateId] = isNaN(val) ? 0 : val;
}

var powerKW      = stateMap[513] || 0;
var currentL1    = stateMap[501] || 0;
var currentL2    = stateMap[502] || 0;
var currentL3    = stateMap[503] || 0;
var voltageL1    = stateMap[553] || 230;
var voltageL2    = stateMap[554] || 230;
var voltageL3    = stateMap[555] || 230;
var energySess   = stateMap[521] || 0;
var energyTotal  = stateMap[552] || 0;
var opMode       = stateMap[544] || 0;
var setCurrent   = stateMap[520] || 0;

var totalCurrent = currentL1 + currentL2 + currentL3;
var powerL1 = voltageL1 * currentL1;
var powerL2 = voltageL2 * currentL2;
var powerL3 = voltageL3 * currentL3;
var totalPowerW = (powerKW > 0) ? Math.round(powerKW * 1000) : Math.round(powerL1 + powerL2 + powerL3);

var modeToStatus = { 0:0, 1:0, 2:6, 3:2, 4:3, 5:0, 6:4 };
var victronStatus = (modeToStatus[opMode] !== undefined) ? modeToStatus[opMode] : 0;

var measurements = {
    serial:          serial,
    name:            name,
    power:           totalPowerW,
    power_l1:        Math.round(powerL1),
    power_l2:        Math.round(powerL2),
    power_l3:        Math.round(powerL3),
    current:         Math.round(totalCurrent * 10) / 10,
    current_l1:      Math.round(currentL1 * 10) / 10,
    current_l2:      Math.round(currentL2 * 10) / 10,
    current_l3:      Math.round(currentL3 * 10) / 10,
    voltage_l1:      Math.round(voltageL1 * 10) / 10,
    voltage_l2:      Math.round(voltageL2 * 10) / 10,
    voltage_l3:      Math.round(voltageL3 * 10) / 10,
    energy_session:  Math.round(energySess  * 1000) / 1000,
    energy_total:    Math.round(energyTotal * 1000) / 1000,
    status:          victronStatus,
    operation_mode:  opMode,
    set_current:     setCurrent,
    timestamp:       new Date().toISOString()
};

node.log('Laadpaal [' + name + '] ' + totalPowerW + ' W | Status: ' + victronStatus + ' | Sessie: ' + energySess + ' kWh');

var mqttMsg = {
    topic: 'zaptec/' + serial + '/measurements',
    payload: JSON.stringify(measurements),
    retain: true,
    qos: 0
};

var debugMsg = {
    topic: serial,
    payload: measurements
};

return [mqttMsg, debugMsg];

var d = msg.payload;
if (!d || !d.serial) return null;

var statusLabels = {
    0: 'Ontkoppeld',
    1: 'Verbonden',
    2: 'Aan het opladen',
    3: 'Opgeladen',
    4: 'Wacht op zon',
    5: 'Wacht op RFID',
    6: 'Wacht op start',
    7: 'Laag SOC',
    8: 'Aardingsfout'
};

var summary = {
    laadpaal:        d.name,
    serienummer:     d.serial,
    vermogen:        d.power + ' W',
    stroom_l1:       d.current_l1 + ' A',
    stroom_l2:       d.current_l2 + ' A',
    stroom_l3:       d.current_l3 + ' A',
    spanning_l1:     d.voltage_l1 + ' V',
    sessie_energie:  d.energy_session + ' kWh',
    totaal_energie:  d.energy_total + ' kWh',
    status:          statusLabels[d.status] || 'Onbekend (' + d.status + ')',
    bijgewerkt:      d.timestamp
};

msg.payload = summary;
return msg;
